begin;
create function pg_temp.activity_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ACTIVITY TEST FAILED: %',label;end if;end$$;
create function pg_temp.activity_denied(statement text,expected text default '42501') returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=expected then return;end if;raise;end;raise exception 'Unexpected permission: %',statement;end$$;
insert into auth.users(id,email,email_confirmed_at) values
 ('10000000-0000-4000-8000-000000000001','activity-owner@example.invalid',now()),
 ('20000000-0000-4000-8000-000000000002','activity-peer@example.invalid',now()),
 ('30000000-0000-4000-8000-000000000003','activity-other@example.invalid',now());
update realm_private.accounts set state='active';update public.homes set privacy='friends';
insert into public.friendships(requester,addressee,status) values('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000002','accepted');
insert into public.spaces(id,name) values('70000000-0000-4000-8000-000000000007','Activity');
insert into public.space_members(space_id,user_id,role) values('70000000-0000-4000-8000-000000000007','10000000-0000-4000-8000-000000000001','owner'),('70000000-0000-4000-8000-000000000007','20000000-0000-4000-8000-000000000002','member');
insert into public.channels(id,space_id,name) values('80000000-0000-4000-8000-000000000008','70000000-0000-4000-8000-000000000007','general');
select pg_temp.activity_assert(not has_function_privilege('anon','public.world_activity_snapshot(text,uuid)','execute'),'anonymous denied');
select pg_temp.activity_assert(not has_table_privilege('authenticated','realm_private.world_activity','SELECT'),'private activity rows');
select pg_temp.activity_assert(not has_table_privilege('authenticated','realm_private.room_speech','INSERT'),'no forged author');
set local role authenticated;select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select pg_temp.activity_denied($q$select public.world_activity_snapshot('home',auth.uid())$q$);
select public.enter_home(auth.uid(),'10000000-0000-4000-8000-000000000011');
select public.world_activity_update('home',auth.uid(),true,true,'desk',clock_timestamp()+interval '25 minutes');
select pg_temp.activity_assert((public.world_activity_snapshot('home',auth.uid())->'activity'->0->>'user_id')=auth.uid()::text,'author from auth');
select public.room_say(auth.uid(),'Hello from my desk','10000000-0000-4000-8000-000000000012');
select public.room_say(auth.uid(),'Hello from my desk','10000000-0000-4000-8000-000000000012');
select pg_temp.activity_assert(jsonb_array_length(public.world_activity_snapshot('home',auth.uid())->'messages')=1,'idempotent room send');
select pg_temp.activity_assert(public.world_activity_snapshot('home',auth.uid())->'activity'->0->>'typing_until' is null,'send clears typing');
select pg_temp.activity_denied($q$select public.room_say(auth.uid(),repeat('x',121),gen_random_uuid())$q$,'23514');
select pg_temp.activity_denied($q$select public.world_activity_update('home',auth.uid(),null,true,'desk',clock_timestamp()+interval '26 minutes')$q$,'22023');
select public.world_activity_update('channel','80000000-0000-4000-8000-000000000008',true);
select public.message_send('channel','80000000-0000-4000-8000-000000000008','Channel speech','10000000-0000-4000-8000-000000000013');
select pg_temp.activity_assert(public.world_activity_snapshot('channel','80000000-0000-4000-8000-000000000008')->'activity'->0->>'typing_until' is null,'channel send atomically clears typing');
select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select public.enter_home('10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000011');
select pg_temp.activity_assert(public.world_activity_snapshot('home','10000000-0000-4000-8000-000000000001')->'messages'->0->>'body'='Hello from my desk','current visitor hears room speech');
select pg_temp.activity_assert(public.world_activity_snapshot('channel','80000000-0000-4000-8000-000000000008')->'messages'->0->>'body'='Channel speech','member hears channel speech');
select set_config('request.jwt.claim.sub','30000000-0000-4000-8000-000000000003',true);
select pg_temp.activity_denied($q$select public.world_activity_snapshot('channel','80000000-0000-4000-8000-000000000008')$q$);
select pg_temp.activity_denied($q$select public.world_activity_update('home','10000000-0000-4000-8000-000000000001',true)$q$);
reset role;
select pg_temp.activity_assert(jsonb_array_length(realm_private.own_export('10000000-0000-4000-8000-000000000001')->'room_speech')=1,'authored room speech included in own export');
update realm_private.world_activity set seen_at=clock_timestamp()-interval '11 seconds';
update realm_private.room_speech set created_at=clock_timestamp()-interval '25 hours';
set local role authenticated;select set_config('request.jwt.claim.sub','20000000-0000-4000-8000-000000000002',true);
select pg_temp.activity_assert(jsonb_array_length(public.world_activity_snapshot('home','10000000-0000-4000-8000-000000000001')->'messages')=0,'old room speech not returned');
select pg_temp.activity_assert(jsonb_array_length(public.world_activity_snapshot('home','10000000-0000-4000-8000-000000000001')->'activity')=0,'stale disconnected focus not returned');
reset role;update public.homes set privacy='private' where owner_id='10000000-0000-4000-8000-000000000001';
set local role authenticated;select pg_temp.activity_denied($q$select public.world_activity_snapshot('home','10000000-0000-4000-8000-000000000001')$q$);
reset role;select realm_private.maintenance();
select pg_temp.activity_assert((select count(*)=0 from realm_private.room_speech),'maintenance deletes expired speech');
select pg_temp.activity_assert(not has_function_privilege('authenticated','realm_private.maintenance()','execute'),'maintenance stays service only');
rollback;
